    53→    /// Upload a FIT file to Garmin Connect
    54→    ///
    55→    /// Returns the sync record with upload status
    56→    pub async fn upload_activity(
    57→        &self,
    58→        ride_id: &Uuid,
    59→        _fit_data: &[u8],
    60→    ) -> Result<SyncRecord, SyncError> {
    61→        let _token = self
    62→            .access_token
    63→            .read()
    64→            .await
    65→            .clone()
    66→            .ok_or(SyncError::NotConfigured(SyncPlatform::GarminConnect))?;
    67→
    68→        let record_id = Uuid::new_v4();
    69→
    70→        tracing::info!(
    71→            "Uploading activity {} to Garmin Connect (record: {})",
    72→            ride_id,
    73→            record_id
    74→        );
    75→
    76→        // Garmin Connect uses a different upload flow than Strava
    77→        // It typically uses the Garmin Connect API or the GarminConnect-Upload endpoint
    78→
    79→        // TODO: Make actual HTTP request to Garmin Connect
    80→        // POST https://connect.garmin.com/modern/proxy/upload-service/upload/.fit
    81→        //
    82→        // Multipart form data:
    83→        // - file: FIT file data
    84→        //
    85→        // Headers:
    86→        // - Authorization: Bearer {token}
    87→        // - NK: various required Garmin headers
    88→
    89→        // For now, create a pending record
    90→        let record = SyncRecord {
    91→            id: record_id,
    92→            ride_id: *ride_id,
    93→            platform: SyncPlatform::GarminConnect,
    94→            status: SyncRecordStatus::Pending,
    95→            external_id: None,
    96→            external_url: None,
    97→            created_at: Utc::now(),
    98→            completed_at: None,
    99→            error_message: None,
   100→            retry_count: 0,
   101→        };
   102→
   103→        tracing::debug!("Garmin Connect upload initiated: {:?}", record);
   104→
   105→        Ok(record)
   106→    }
