   583→                    SyncError::NetworkError(format!("Connection failed: {}", e))
   584→                } else {
   585→                    SyncError::NetworkError(format!("Failed to fetch user profile: {}", e))
   586→                }
   587→            })?;
   588→
   589→        let status_code = response.status();
   590→        let body = response
   591→            .text()
   592→            .await
   593→            .map_err(|e| SyncError::NetworkError(format!("Failed to read response body: {}", e)))?;
   594→
   595→        // Handle rate limiting (429 Too Many Requests)
   596→        if status_code == reqwest::StatusCode::TOO_MANY_REQUESTS {
   597→            tracing::warn!("Garmin Connect API rate limit exceeded");
   598→            return Err(SyncError::RateLimited);
   599→        }
   600→
   601→        // Handle unauthorized (401)
   602→        if status_code == reqwest::StatusCode::UNAUTHORIZED {
   603→            tracing::warn!(
   604→                "Garmin Connect API returned 401 Unauthorized - token may be expired or revoked"
   605→            );
   606→            return Err(SyncError::TokenExpired);
   607→        }
   608→
   609→        // Handle forbidden (403) - often means token issues
   610→        if status_code == reqwest::StatusCode::FORBIDDEN {
   611→            tracing::warn!("Garmin Connect API returned 403 Forbidden - token may be invalid");
   612→            return Err(SyncError::TokenExpired);
   613→        }
   614→
   615→        // Handle other errors
   616→        if !status_code.is_success() {
