   620→                    "Garmin error: {}",
   621→                    error_response
   622→                )));
   623→            }
   624→            tracing::error!(
   625→                "Garmin Connect profile fetch failed with status {}: {}",
   626→                status_code,
   627→                body
   628→            );
   629→            return Err(SyncError::ApiError(format!(
   630→                "Failed to fetch profile with status {}: {}",
   631→                status_code, body
   632→            )));
   633→        }
   634→
   635→        // Parse successful response
   636→        let profile_response: GarminSocialProfileResponse =
   637→            serde_json::from_str(&body).map_err(|e| {
   638→                SyncError::ApiError(format!("Failed to parse profile response: {}", e))
   639→            })?;
   640→
   641→        tracing::info!(
   642→            "Fetched Garmin Connect user profile: {} (id: {})",
   643→            profile_response.display_name,
   644→            profile_response.user_id
   645→        );
