   692→    /// Deauthorize application
   693→    ///
   694→    /// Revokes the application's access to the user's Garmin Connect account by POSTing
   695→    /// to the revoke endpoint. This invalidates the access token on Garmin's side
   696→    /// and clears the local token.
   697→    ///
   698→    /// Note: Garmin Connect's OAuth 2.0 implementation may not support standard
   699→    /// token revocation. This method attempts to call the revoke endpoint but
   700→    /// will succeed regardless if the local token is cleared.
   701→    ///
   702→    /// # Returns
   703→    /// Ok(()) if deauthorization was successful or the token was already invalid.
   704→    /// The local token is cleared regardless of the API response.
   705→    pub async fn deauthorize(&self) -> Result<(), SyncError> {
   706→        let token = self
   707→            .access_token
   708→            .read()
   709→            .await
   710→            .clone()
   711→            .ok_or(SyncError::NotConfigured(SyncPlatform::GarminConnect))?;
   712→
   713→        tracing::info!("Deauthorizing Garmin Connect");
   714→
   715→        // POST to Garmin's revoke endpoint
   716→        // Note: Garmin Connect OAuth may not support standard revocation
   717→        let url = format!("{}/revoke", self.oauth_base_url);
   718→
   719→        let response = self
   720→            .http_client
   721→            .post(&url)
   722→            .bearer_auth(&token)
   723→            .send()
   724→            .await;
   725→
   726→        // Always clear local token, even if the API call fails
   727→        // This ensures the usercan disconnect even with network issues
   728→        self.clear_token().await;
   729→
   730→        // Now handle the response
   731→        let response = match response {
   732→            Ok(r) => r,
   733→            Err(e) => {
   734→                tracing::warn!(
   735→                    "Failed to call Garmin Connect revoke endpoint: {}. Local token cleared.",
   736→                    e
   737→                );
   738→                // Still consider this a success since local token is cleared
   739→                return Ok(());
   740→            }
   741→        };
   742→
   743→        let status_code = response.status();
   744→
   745→        // Handle rate limiting (429 Too Many Requests)
   746→        if status_code == reqwest::StatusCode::TOO_MANY_REQUESTS {
   747→            tracing::warn!(
   748→                "Garmin Connect API rate limit exceeded during deauthorization. Local token cleared."
   749→            );
   750→            // Token is already cleared locally, so this is still a success from user perspective
   751→            return Ok(());
   752→        }
   753→
   754→        // Handle unauthorized (401) - token was already invalid/revoked
   755→        if status_code == reqwest::StatusCode::UNAUTHORIZED {
   756→            tracing::info!("Garmin Connect token was already invalid or revoked. Local token cleared.");
   757→            return Ok(());
   758→        }
   759→
   760→        // Handle not found (404) - endpoint may not exist
   761→        if status_code == reqwest::StatusCode::NOT_FOUND {
   762→            tracing::info!(
   763→                "Garmin Connect revoke endpoint not found. Local token cleared."
   764→            );
   765→            return Ok(());
   766→        }
   767→
   768→        // Handle other errors
   769→        if !status_code.is_success() {
   770→            let body = response.text().await.unwrap_or_default();
771→            if let Ok(error_response) = serde_json::from_str::<GarminApiError>(&body) {
   772→                tracing::warn!(
   773→                    "Garmin Connect revoke returned error: {}. Local token cleared.",
   774→                    error_response
   775→                );
   776→            } else {
   777→                tracing::warn!(
   778→                    "Garmin Connect revoke returned status {}: {}. Local token cleared.",
   779→                    status_code,
   780→                    body
   781→                );
   782→            }
   783→            // Still consider this a success since local token is cleared
   784→            return Ok(());
   785→        }
   786→
   787→        tracing::info!("Successfully deauthorized from Garmin Connect");
   788→
   789→        Ok(())
   790→    }
