   164→impl SyncErrorExt for SyncError {
   165→    fn category(&self) -> ErrorCategory {
   166→        match self {
   167→            SyncError::NotConfigured(_) => ErrorCategory::Client,
   168→            SyncError::AuthorizationRequired => ErrorCategory::Authentication,
   169→            SyncError::TokenExpired => ErrorCategory::Authentication,
   170→            SyncError::RefreshFailed(_) => ErrorCategory::Authentication,
   171→            SyncError::UploadFailed(msg) => {
   172→                // Check for server errors in the message
   173→                if msg.contains("500") || msg.contains("502") || msg.contains("503") {
   174→                    ErrorCategory::Server
