   465→    /// Handle common HTTP status code errors with consistent logging and error mapping.
   466→    ///
   467→    /// Returns `Some(SyncError)` for known error status codes, or `None` if the
   468→    /// status code should be handled differently by the caller.
   469→    ///
   470→    /// This method handles:
   471→    /// - 429 Too Many Requests → RateLimited
   472→    /// - 401 Unauthorized → TokenExpired
   473→    /// - 403 Forbidden → TokenExpired (often means invalid token)
   474→    /// - 409 Conflict → DuplicateActivity
   475→    fn handle_error_status(
   476→        status: reqwest::StatusCode,
   477→        context: &str,
   478→    ) -> Option<SyncError> {
   479→        match status {
   480→            reqwest::StatusCode::TOO_MANY_REQUESTS => {
   481→                tracing::warn!("Garmin Connect API rate limit exceeded during {}", context);
   482→                Some(SyncError::RateLimited)
   483→            }
   484→            reqwest::StatusCode::UNAUTHORIZED => {
   485→                tracing::warn!(
   486→                    "Garmin Connect API returned 401 Unauthorized during {} - token may be expired or revoked",
   487→                    context
   488→                );
   489→                Some(SyncError::TokenExpired)
   490→            }
   491→            reqwest::StatusCode::FORBIDDEN => {
   492→                tracing::warn!(
   493→                    "Garmin Connect API returned 403 Forbidden during {} - token may be invalid",
   494→                    context
   495→                );
   496→                Some(SyncError::TokenExpired)
   497→            }
   498→            reqwest::StatusCode::CONFLICT => {
   499→                tracing::info!("Garmin Connect returned 409 Conflict during {} - likely duplicate", context);
   500→                Some(SyncError::DuplicateActivity(SyncPlatform::GarminConnect))
   501→            }
   502→            _ => None,
   503→        }
   504→    }
