   506→    /// Map a reqwest error to a SyncError with appropriate categorization.
   507→    ///
   508→    /// This method handles common network error cases:
   509→    /// - Timeout errors → Timeout
   510→    /// - Connection errors → NetworkError (connection failed)
   511→    /// - Other errors → NetworkError (request failed)
   512→    fn map_request_error(err: reqwest::Error, timeout_secs: u64, context: &str) -> SyncError {
   513→        if err.is_timeout() {
   514→            tracing::warn!(
   515→                "Garmin Connect {} request timed out after {} seconds",
   516→                context,
   517→                timeout_secs
   518→            );
   519→            SyncError::Timeout(timeout_secs)
   520→        } else if err.is_connect() {
   521→            tracing::warn!("Failed to connect to Garmin Connect during {}: {}", context, err);
   522→            SyncError::NetworkError(format!("Connection failed: {}", err))
   523→        } else {
   524→            tracing::warn!("Failed to send {} request to Garmin Connect: {}", context, err);
   525→            SyncError::NetworkError(format!("Request failed: {}", err))
   526→        }
   527→    }
