+    /// Get the recommended initial retry delay in seconds
+    pub fn initial_retry_delay_secs(&self) -> u64 {
+        match self {
+            ErrorCategory::Transient => 5,
+            ErrorCategory::RateLimited => DEFAULT_RATE_LIMIT_RETRY_SECS,
+            ErrorCategory::Server => 30,
+            _ => 0, // Non-retryable
