    23→/// Default request timeout in seconds
    24→const DEFAULT_TIMEOUT_SECS: u64 = 60;
    25→
    26→/// Upload timeout in seconds (longer for file uploads)
    27→const UPLOAD_TIMEOUT_SECS: u64 = 120;
