    31→
    32→/// Default Garmin Connect OAuth base URL (for token revocation)
    33→const GARMIN_OAUTH_BASE_URL: &str = "https://connect.garmin.com/oauth-service/oauth";
    34→
    35→/// FIT file header magic bytes
    36→const FIT_HEADER_SIZE: u8 = 14;
    37→const FIT_HEADER_SIGNATURE: &[u8] = b".FIT";
    38→
    39→/// Default retry delay in seconds when rate limited without Retry-After header
    40→const DEFAULT_RATE_LIMIT_RETRY_SECS: u64 = 60;
    41→
    42→/// Maximum retry attempts for transient errors
    43→const MAX_RETRY_ATTEMPTS: u32 = 3;
    44→
    45→/// Error categorization for retry and recovery logic
    46→///
    47→/// Classifies errors into categories that help determine the appropriate
    48→/// recovery strategy.
    49→#[derive(Debug, Clone, Copy, PartialEq, Eq)]
    50→pub enum ErrorCategory {
    51→    /// Transient errors that should be retried (network issues, timeouts)
    52→    Transient,
    53→    /// Rate limit errors that require waiting before retry
    54→    RateLimited,
    55→    /// Authentication errors requiring token refresh or re-authorization
    56→    Authentication,
    57→    /// Client errors that should not be retried (invalid data, bad request)
    58→    Client,
    59→    /// Server errors that may be retried after a delay
    60→    Server,
    61→    /// Permanent errors that should not be retried (duplicate activity)
    62→    Permanent,
    63→}
    64→
    65→impl ErrorCategory {
    66→    /// Check if errors in this category should be retried
    67→    pub fn is_retryable(&self) -> bool {
    68→        matches!(
    69→            self,
    70→            ErrorCategory::Transient | ErrorCategory::RateLimited | ErrorCategory::Server
    71→        )
    72→    }
    73→
    74→    /// Get the recommended initial retry delay in seconds
    75→    pub fn initial_retry_delay_secs(&self) -> u64 {
    76→        match self {
    77→            ErrorCategory::Transient => 5,
    78→            ErrorCategory::RateLimited => DEFAULT_RATE_LIMIT_RETRY_SECS,
    79→            ErrorCategory::Server => 30,
    80→            _ => 0, // Non-retryable
    81→        }
    82→    }
    83→
    84→    /// Get the maximum number of retry attempts for this category
    85→    pub fn max_retry_attempts(&self) -> u32 {
    86→        match self {
    87→            ErrorCategory::Transient => MAX_RETRY_ATTEMPTS,
    88→            ErrorCategory::RateLimited => 1, // Wait and retry once
    89→            ErrorCategory::Server => 2,
    90→            _ => 0, // Non-retryable
    91→        }
    92→    }
    93→}
    94→
    95→/// Ratelimit information extracted from API response
    96→#[derive(Debug, Clone)]
    97→pub struct RateLimitInfo {
    98→    /// Seconds to wait before retrying (from Retry-After header or default)
    99→    pub retry_after_secs: u64,
   100→    /// Whether this is a hard limit (daily) vs soft limit (per-minute)
   101→    pub is_hard_limit: bool,
   102→}
   103→
   104→impl Default for RateLimitInfo {
   105→    fn default() -> Self {
   106→        Self {
   107→            retry_after_secs: DEFAULT_RATE_LIMIT_RETRY_SECS,
   108→            is_hard_limit: false,
   109→        }
   110→    }
   111→}
   112→
   113→impl RateLimitInfo {
   114→    /// Create rate limit info from HTTP response headers
   115→    pub fn from_headers(headers: &reqwest::header::HeaderMap) -> Self {
   116→        // Try to parse Retry-After header
   117→        let retry_after_secs = headers
   118→            .get("retry-after")
   119→            .and_then(|v| v.to_str().ok())
   120→            .and_then(|v| v.parse::<u64>().ok())
   121→            .unwrap_or(DEFAULT_RATE_LIMIT_RETRY_SECS);
   122→
   123→        // Check for daily limit indicator (varies by API)
   124→        let is_hard_limit = headers
   125→            .get("x-ratelimit-remaining")
   126→            .and_then(|v| v.to_str().ok())
   127→            .and_then(|v| v.parse::<u64>().ok())
   128→            .map(|remaining| remaining == 0)
   129→            .unwrap_or(false);
   130→
   131→        Self {
   132→            retry_after_secs,
   133→            is_hard_limit,
   134→        }
   135→    }
   136→
   137→    /// Get the retry delay as a Duration
   138→    pub fn retry_delay(&self) -> Duration {
   139→        Duration::from_secs(self.retry_after_secs)
   140→    }
   141→}
   142→
   143→/// Extension trait for SyncError to support error categorization and retry logic
   144→pub trait SyncErrorExt {
   145→    /// Get the error category for retry/recovery logic
   146→    fn category(&self) -> ErrorCategory;
   147→
   148→    /// Check if this error should be retried
   149→    fn is_retryable(&self) -> bool;
   150→
   151→    /// Check if this error requires authentication refresh
   152→    fn requires_auth_refresh(&self) -> bool;
   153→
   154→    /// Check if this error is due to rate limiting
   155→    fn is_rate_limited(&self) -> bool;
   156→
   157→    /// Check if this error is due to a duplicate activity
   158→    fn is_duplicate(&self) -> bool;
   159→
   160→    /// Get the recommended retry delay in seconds
   161→    fn retry_delay_secs(&self) -> u64;
   162→}
   163→
   164→impl SyncErrorExt for SyncError {
   165→    fn category(&self) -> ErrorCategory {
   166→        match self {
   167→            SyncError::NotConfigured(_) => ErrorCategory::Client,
   168→            SyncError::AuthorizationRequired => ErrorCategory::Authentication,
   169→            SyncError::TokenExpired => ErrorCategory::Authentication,
   170→            SyncError::RefreshFailed(_) => ErrorCategory::Authentication,
   171→            SyncError::UploadFailed(msg) => {
   172→                // Check for server errors in the message
   173→                if msg.contains("500") || msg.contains("502") || msg.contains("503") {
   174→                    ErrorCategory::Server
   175→                } else {
   176→                    ErrorCategory::Client
   177→                }
   178→            }
   179→            SyncError::ApiError(msg) => {
   180→                if msg.contains("500") || msg.contains("502") || msg.contains("503") {
   181→                    ErrorCategory::Server
   182→                } else {
   183→                    ErrorCategory::Client
   184→                }
   185→            }
   186→            SyncError::CredentialError(_) => ErrorCategory::Permanent,
   187→            SyncError::NetworkError(_) => ErrorCategory::Transient,
   188→            SyncError::DuplicateActivity(_) => ErrorCategory::Permanent,
   189→            SyncError::InvalidFitFile(_) => ErrorCategory::Client,
   190→            SyncError::Timeout(_) => ErrorCategory::Transient,
   191→            SyncError::RateLimited => ErrorCategory::RateLimited,
   192→        }
   193→    }
   194→
   195→    fn is_retryable(&self) -> bool {
   196→        self.category().is_retryable()
   197→    }
   198→
   199→    fn requires_auth_refresh(&self) -> bool {
   200→        matches!(self.category(), ErrorCategory::Authentication)
   201→    }
   202→
   203→    fn is_rate_limited(&self) -> bool {
   204→        matches!(self, SyncError::RateLimited)
   205→    }
   206→
   207→    fn is_duplicate(&self) -> bool {
   208→        matches!(self, SyncError::DuplicateActivity(_))
   209→    }
   210→
   211→    fn retry_delay_secs(&self) -> u64 {
   212→        self.category().initial_retry_delay_secs()
   213→    }
   214→}
