    95→/// Rate limit information extracted from API response
    96→#[derive(Debug, Clone)]
    97→pub struct RateLimitInfo {
    98→    /// Seconds to wait before retrying (from Retry-After header or default)
    99→    pub retry_after_secs: u64,
   100→    /// Whether this is a hard limit (daily) vs soft limit (per-minute)
   101→    pub is_hard_limit: bool,
   102→}
   103→
   104→impl Default for RateLimitInfo {
   105→    fn default() -> Self {
   106→        Self {
   107→            retry_after_secs: DEFAULT_RATE_LIMIT_RETRY_SECS,
   108→            is_hard_limit: false,
   109→        }
   110→    }
   111→}
   112→
   113→impl RateLimitInfo {
   114→    /// Create rate limit info from HTTP response headers
   115→    pub fn from_headers(headers: &reqwest::header::HeaderMap) -> Self {
   116→        // Try to parse Retry-After header
   117→        let retry_after_secs = headers
   118→            .get("retry-after")
   119→            .and_then(|v| v.to_str().ok())
   120→            .and_then(|v| v.parse::<u64>().ok())
   121→            .unwrap_or(DEFAULT_RATE_LIMIT_RETRY_SECS);
   122→
   123→        // Check for daily limit indicator (varies by API)
   124→        let is_hard_limit = headers
   125→            .get("x-ratelimit-remaining")
   126→            .and_then(|v| v.to_str().ok())
   127→            .and_then(|v| v.parse::<u64>().ok())
   128→            .map(|remaining| remaining == 0)
   129→            .unwrap_or(false);
   130→
   131→        Self {
   132→            retry_after_secs,
   133→            is_hard_limit,
   134→        }
   135→    }
   136→
   137→    /// Get the retry delay as a Duration
   138→    pub fn retry_delay(&self) -> Duration {
   139→        Duration::from_secs(self.retry_after_secs)
   140→    }
   141→}
