   143→/// Extension trait for SyncError to support error categorization and retry logic
   144→pub trait SyncErrorExt {
   145→    /// Get the error category for retry/recovery logic
   146→    fn category(&self) -> ErrorCategory;
   147→
   148→    /// Check if this error should be retried
   149→    fn is_retryable(&self) -> bool;
   150→
   151→    /// Check if this error requires authentication refresh
   152→    fn requires_auth_refresh(&self) -> bool;
   153→
   154→    /// Check if this error is due to rate limiting
   155→    fn is_rate_limited(&self) -> bool;
   156→
   157→    /// Check if this error is due to a duplicate activity
   158→    fn is_duplicate(&self) -> bool;
   159→
   160→    /// Get the recommended retry delay in seconds
   161→    fn retry_delay_secs(&self) -> u64;
   162→}
   163→
   164→impl SyncErrorExt for SyncError {
   165→    fn category(&self) -> ErrorCategory {
   166→        match self {
   167→            SyncError::NotConfigured(_) => ErrorCategory::Client,
   168→            SyncError::AuthorizationRequired => ErrorCategory::Authentication,
   169→            SyncError::TokenExpired => ErrorCategory::Authentication,
   170→            SyncError::RefreshFailed(_) => ErrorCategory::Authentication,
   171→            SyncError::UploadFailed(msg) => {
   172→                // Check for server errors in the message
   173→                if msg.contains("500") || msg.contains("502") || msg.contains("503") {
   174→                    ErrorCategory::Server
   175→                } else {
   176→                    ErrorCategory::Client
   177→                }
   178→            }
   179→            SyncError::ApiError(msg) => {
   180→                if msg.contains("500") || msg.contains("502") || msg.contains("503") {
   181→                    ErrorCategory::Server
   182→                } else {
   183→                    ErrorCategory::Client
   184→                }
   185→            }
   186→            SyncError::CredentialError(_) => ErrorCategory::Permanent,
   187→            SyncError::NetworkError(_) => ErrorCategory::Transient,
   188→            SyncError::DuplicateActivity(_) => ErrorCategory::Permanent,
   189→            SyncError::InvalidFitFile(_) => ErrorCategory::Client,
   190→            SyncError::Timeout(_) => ErrorCategory::Transient,
   191→            SyncError::RateLimited => ErrorCategory::RateLimited,
   192→        }
   193→    }
   194→
   195→    fn is_retryable(&self) -> bool {
   196→        self.category().is_retryable()
   197→    }
   198→
   199→    fn requires_auth_refresh(&self) -> bool {
   200→        matches!(self.category(), ErrorCategory::Authentication)
   201→    }
   202→
   203→    fn is_rate_limited(&self) -> bool {
   204→        matches!(self, SyncError::RateLimited)
   205→    }
   206→
   207→    fn is_duplicate(&self) -> bool {
   208→        matches!(self, SyncError::DuplicateActivity(_))
   209→    }
   210→
   211→    fn retry_delay_secs(&self) -> u64 {
   212→        self.category().initial_retry_delay_secs()
   213→    }
   214→}
