   563→    /// Validate FIT file data before upload.
   564→    ///
   565→    /// Checks:
   566→    /// - Minimum file size (at least header size)
   567→    /// - FIT file signature (".FIT" at offset 8-12)
   568→    /// - Header size byte is valid
   569→    ///
   570→    /// # Arguments
   571→    /// * `fit_data` - The FIT file bytes
   572→    ///
   573→    /// # Returns
   574→    /// Ok(()) if valid, or InvalidFitFile error with description
   575→    pub fn validate_fit_file(fit_data: &[u8]) -> Result<(), SyncError> {
   576→        // Check minimum size (header must be at least 12 bytes for basic FIT)
   577→        if fit_data.len() < 12 {
   578→            return Err(SyncError::InvalidFitFile(format!(
   579→                "File too small: {} bytes (minimum 12 bytes required)",
   580→                fit_data.len()
   581→            )));
   582→        }
   583→
   584→        // Check header size byte (first byte)
   585→        let header_size = fit_data[0];
   586→        if header_size != 12 && header_size != FIT_HEADER_SIZE {
   587→            return Err(SyncError::InvalidFitFile(format!(
   588→                "Invalid header size: {} (expected 12 or 14)",
   589→                header_size
   590→            )));
   591→        }
   592→
   593→        // Check FIT signature at bytes 8-11
   594→        if fit_data.len() >= 12 {
   595→            let signature = &fit_data[8..12];
   596→            if signature != FIT_HEADER_SIGNATURE {
   597→                return Err(SyncError::InvalidFitFile(
   598→                    "Missing '.FIT' signature in header".to_string(),
   599→                ));
   600→            }
   601→        }
   602→
   603→        // Check total file size is reasonable (at least header + some data)
   604→        let min_expected_size = header_size as usize + 2; // header + at least CRC
   605→        if fit_data.len() < min_expected_size {
   606→            return Err(SyncError::InvalidFitFile(format!(
   607→                "File truncated: {} bytes (expected at least {})",
   608→                fit_data.len(),
   609→                min_expected_size
   610→            )));
   611→        }
   612→
   613→        Ok(())
   614→    }
