  1026→/// Keyring-based credential store
  1027→///
  1028→/// Stores OAuth tokens securely using the OS credential store:
  1029→/// - Windows: Windows Credential Manager
  1030→/// - macOS: macOS Keychain
  1031→/// - Linux: Secret Service (via libsecret)
  1032→pub struct KeyringCredentialStore {
  1033→    service_name: String,
  1034→    /// Cache of which platforms have credentials (for fast synchronous checks)
  1035→    credentials_cache: Mutex<HashMap<SyncPlatform, bool>>,
  1036→}
  1037→
  1038→impl KeyringCredentialStore {
  1039→    /// Create a new keyring credential store.
  1040→    ///
  1041→    /// # Arguments
  1042→    /// * `service_name` - The service name used for keyring entries (e.g., "RustRide")
  1043→    pub fn new(service_name: impl Into<String>) -> Self {
  1044→        Self {
  1045→            service_name: service_name.into(),
  1046→            credentials_cache: Mutex::new(HashMap::new()),
  1047→        }
  1048→    }
  1049→
  1050→    /// Get the keyring username for a platform.
  1051→    fn key_for_platform(&self, platform: SyncPlatform) -> String {
  1052→        format!("{:?}", platform).to_lowercase()
  1053→    }
  1054→
  1055→    /// Create a keyring entry for the given platform.
  1056→    fn entry_for_platform(
  1057→        &self,
  1058→        platform: SyncPlatform,
  1059→    ) -> Result<keyring::Entry, SyncError> {
  1060→        let key = self.key_for_platform(platform);
  1061→        keyring::Entry::new(&self.service_name, &key)
  1062→            .map_err(|e| SyncError::CredentialError(format!("Failed to create keyring entry: {}", e)))
  1063→    }
  1064→
  1065→    /// Update the credentials cache.
  1066→    fn update_cache(&self, platform: SyncPlatform, has_creds: bool) {
  1067→        if let Ok(mut cache) = self.credentials_cache.lock() {
  1068→            cache.insert(platform, has_creds);
  1069→        }
  1070→    }
  1071→}
  1072→
  1073→impl CredentialStore for KeyringCredentialStore {
  1074→    async fn store_tokens(
  1075→        &self,
  1076→        platform: SyncPlatform,
  1077→        tokens: &TokenResponse,
  1078→    ) -> Result<(), SyncError> {
  1079→        // Serialize tokens to JSON
  1080→        let json = serde_json::to_string(tokens)
  1081→            .map_err(|e| SyncError::CredentialError(format!("Failed to serialize tokens: {}", e)))?;
  1082→
  1083→        // Create keyring entry and store
  1084→        let entry = self.entry_for_platform(platform)?;
  1085→        entry
  1086→            .set_password(&json)
  1087→            .map_err(|e| SyncError::CredentialError(format!("Failed to store credentials: {}", e)))?;
  1088→
  1089→        // Update cache
  1090→        self.update_cache(platform, true);
  1091→
  1092→        tracing::debug!("Stored tokens for {:?} in OS keyring", platform);
  1093→
  1094→        Ok(())
  1095→    }
  1096→
  1097→    async fn get_tokens(&self, platform: SyncPlatform) -> Result<Option<TokenResponse>, SyncError> {
  1098→        let entry = self.entry_for_platform(platform)?;
  1099→
  1100→        match entry.get_password() {
  1101→            Ok(json) => {
  1102→                // Parse stored JSON back to TokenResponse
  1103→                let tokens: StoredTokenResponse = serde_json::from_str(&json)
  1104→                    .map_err(|e| SyncError::CredentialError(format!("Failed to parse stored tokens: {}", e)))?;
  1105→
  1106→                // Convert to TokenResponse
  1107→                let token_response = tokens.into_token_response()?;
  1108→
  1109→                // Update cache
  1110→                self.update_cache(platform, true);
  1111→
  1112→                tracing::debug!("Retrieved tokens for {:?} from OS keyring", platform);
  1113→                Ok(Some(token_response))
  1114→            }
  1115→            Err(keyring::Error::NoEntry) => {
  1116→                // No credentials stored - this is not an error
  1117→                self.update_cache(platform, false);
  1118→                tracing::debug!("No tokens found for {:?} in OS keyring", platform);
  1119→                Ok(None)
  1120→            }
  1121→            Err(e) => {
  1122→                // Other keyring errors
  1123→                tracing::error!("Failed to retrieve tokens for {:?}: {}", platform, e);
  1124→                Err(SyncError::CredentialError(format!(
  1125→                    "Failed to retrieve credentials: {}",
  1126→                    e
  1127→                )))
  1128→            }
  1129→        }
  1130→    }
  1131→
  1132→    async fn delete_tokens(&self, platform: SyncPlatform) -> Result<(), SyncError> {
  1133→        let entry = self.entry_for_platform(platform)?;
  1134→
  1135→        match entry.delete_credential() {
  1136→            Ok(()) => {
  1137→                self.update_cache(platform, false);
  1138→                tracing::debug!("Deleted tokens for {:?} from OS keyring", platform);
  1139→                Ok(())
  1140→            }
  1141→            Err(keyring::Error::NoEntry) => {
  1142→                // Already deleted or never existed - not an error
  1143→                self.update_cache(platform, false);
  1144→                tracing::debug!("No tokens to delete for {:?}", platform);
  1145→                Ok(())
  1146→            }
  1147→            Err(e) => {
  1148→                tracing::error!("Failed to delete tokens for {:?}: {}", platform, e);
  1149→                Err(SyncError::CredentialError(format!(
  1150→                    "Failed to delete credentials: {}",
  1151→                    e
  1152→                )))
  1153→            }
  1154→        }
  1155→    }
  1156→
  1157→    fn has_credentials(&self, platform: SyncPlatform) -> bool {
  1158→        // First check cache for fast lookup
  1159→        if let Ok(cache) = self.credentials_cache.lock() {
  1160→            if let Some(&has_creds) = cache.get(&platform) {
  1161→                return has_creds;
  1162→            }
  1163→        }
  1164→
  1165→        // Cache miss - check keyring directly
  1166→        let has_creds = match self.entry_for_platform(platform) {
  1167→            Ok(entry) => entry.get_password().is_ok(),
  1168→            Err(_) => false,
  1169→        };
  1170→
  1171→        // Update cache
  1172→        self.update_cache(platform, has_creds);
  1173→
  1174→        has_creds
  1175→    }
  1176→}
