  1178→/// Stored token response format for JSON serialization/deserialization.
  1179→/// This mirrors TokenResponse but with string dates for JSON compatibility.
  1180→#[derive(Debug, Deserialize)]
  1181→struct StoredTokenResponse {
  1182→    access_token: String,
