    32→/// Trait for providing token refresh functionality to GarminClient.
    33→///
    34→/// Implement this trait to enable automatic token refresh when the access token
    35→/// expires during API calls. When a `TokenExpired` error is encountered, the
    36→/// client will call `refresh_token()` to get a new access token and retry the
    37→/// request.
    38→///
    39→/// # Example
    40→///
    41→/// ```ignore
    42→/// use std::sync::Arc;
    43→/// use tokio::sync::RwLock;
    44→///
    45→/// struct MyTokenRefresher {
    46→///     oauth_handler: Arc<OAuthHandler>,
    47→/// }
    48→///
    49→/// impl TokenRefresher for MyTokenRefresher {
    50→///     fn refresh_token(&self) -> TokenRefreshResult {
    51→///         let handler = self.oauth_handler.clone();
    52→///         Box::pin(async move {
    53→///             let tokens = handler.refresh_token(SyncPlatform::GarminConnect).await?;
    54→///             Ok(tokens.access_token)
    55→///         })
    56→///     }
    57→/// }
    58→/// ```
    59→pub trait TokenRefresher: Send + Sync {
    60→    /// Refresh the access token and return the new token.
    61→    ///
    62→    /// This method is called when the client encounters a `TokenExpired` error.
    63→    /// It should:
    64→    /// 1. Use the stored refresh token to get new access/refresh tokens
    65→    /// 2. Store the new tokens appropriately
    66→    /// 3. Return the new access token
    67→    ///
    68→    /// # Returns
    69→    /// A future that resolves to the new access token or an error.
    70→    ///
    71→    /// # Errors
    72→    /// - `AuthorizationRequired` - If the refresh token is also expired
    73→    /// - `RefreshFailed` - If the refresh request fails for other reasons
    74→    /// - `NetworkError` - If the refresh request fails due to network issues
    75→    fn refresh_token(&self) -> TokenRefreshResult;
    76→}
