   100→/// Error categorization for retry and recovery logic
   101→///
   102→/// Classifies errors into categories that help determine the appropriate
   103→/// recovery strategy.
   104→#[derive(Debug, Clone, Copy, PartialEq, Eq)]
   105→pub enum ErrorCategory {
   106→    /// Transient errors that should be retried (network issues, timeouts)
   107→    Transient,
   108→    /// Rate limit errors that require waiting before retry
   109→    RateLimited,
   110→    /// Authentication errors requiring token refresh or re-authorization
   111→    Authentication,
   112→    /// Client errors that should not be retried (invalid data, bad request)
   113→    Client,
   114→    /// Server errors that may be retried after a delay
   115→    Server,
   116→    /// Permanent errors that should not be retried (duplicate activity)
   117→    Permanent,
   118→}
   119→
   120→impl ErrorCategory {
   121→    /// Check if errors in this category should be retried
   122→    pub fn is_retryable(&self) -> bool {
   123→        matches!(
   124→            self,
   125→            ErrorCategory::Transient | ErrorCategory::RateLimited | ErrorCategory::Server
   126→        )
   127→    }
   128→
   129→    /// Get the recommended initial retry delay in seconds
   130→    pub fn initial_retry_delay_secs(&self) -> u64 {
   131→        match self {
   132→            ErrorCategory::Transient => 5,
   133→            ErrorCategory::RateLimited => DEFAULT_RATE_LIMIT_RETRY_SECS,
   134→            ErrorCategory::Server => 30,
   135→            _ => 0, // Non-retryable
   136→        }
   137→    }
   138→
   139→    /// Get the maximum number of retry attempts for this category
   140→    pub fn max_retry_attempts(&self) -> u32 {
   141→        match self {
   142→            ErrorCategory::Transient => MAX_RETRY_ATTEMPTS,
   143→            ErrorCategory::RateLimited => 1, // Wait and retry once
   144→            ErrorCategory::Server => 2,
   145→            _ => 0, // Non-retryable
   146→        }
   147→    }
   148→}
