   150→/// Rate limit information extracted from API response
   151→#[derive(Debug, Clone)]
   152→pub struct RateLimitInfo {
   153→    /// Seconds to wait before retrying (from Retry-After header or default)
   154→    pub retry_after_secs: u64,
   155→    /// Whether this is a hard limit (daily) vs soft limit (per-minute)
   156→    pub is_hard_limit: bool,
   157→}
   158→
   159→impl Default for RateLimitInfo {
   160→    fn default() -> Self {
   161→        Self {
   162→            retry_after_secs: DEFAULT_RATE_LIMIT_RETRY_SECS,
   163→            is_hard_limit: false,
   164→        }
   165→    }
   166→}
   167→
   168→impl RateLimitInfo {
   169→    /// Create rate limit info from HTTP response headers
   170→    pub fn from_headers(headers: &reqwest::header::HeaderMap) -> Self {
   171→        // Try to parse Retry-After header
   172→        let retry_after_secs = headers
   173→            .get("retry-after")
   174→            .and_then(|v| v.to_str().ok())
   175→            .and_then(|v| v.parse::<u64>().ok())
   176→            .unwrap_or(DEFAULT_RATE_LIMIT_RETRY_SECS);
   177→
   178→        // Check for daily limit indicator (varies by API)
   179→        let is_hard_limit = headers
   180→            .get("x-ratelimit-remaining")
   181→            .and_then(|v| v.to_str().ok())
   182→            .and_then(|v| v.parse::<u64>().ok())
   183→            .map(|remaining| remaining == 0)
   184→            .unwrap_or(false);
   185→
   186→        Self {
   187→            retry_after_secs,
   188→            is_hard_limit,
   189→        }
   190→    }
   191→
   192→    /// Get the retry delay as a Duration
   193→    pub fn retry_delay(&self) -> Duration {
   194→        Duration::from_secs(self.retry_after_secs)
   195→    }
   196→}
